import{at as e,it as t,n,vt as r}from"./chunks/framework.UwwvkjGo.js";var i=JSON.parse(`{"title":"Console TUI wave 1 review","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Console TUI wave 1 review"}],["meta",{"property":"og:description","content":""}],["meta",{"property":"og:url","content":"https://jsprismarine.github.io/JSPrismarine/research/console-tui/review-wave1"}],["link",{"rel":"canonical","href":"https://jsprismarine.github.io/JSPrismarine/research/console-tui/review-wave1"}]],"editSource":{"kind":"file","url":"https://github.com/JSPrismarine/JSPrismarine/edit/master/docs/research/console-tui/review-wave1.md"}},"headers":[],"relativePath":"research/console-tui/review-wave1.md","filePath":"research/console-tui/review-wave1.md","lastUpdated":1794040891000}`),a={name:`research/console-tui/review-wave1.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e('<div><h1 id="console-tui-wave-1-review" tabindex="-1">Console TUI wave 1 review <a class="header-anchor" href="#console-tui-wave-1-review" aria-label="Permalink to “Console TUI wave 1 review”">​</a></h1><p>Reviewed the commits from <code>1990d875c3</code> to <code>806b499de5</code> that touch <code>packages/logger</code>, <code>packages/console-protocol</code>, <code>packages/console/src/{theme,log,input,status,keymap}</code>, and <code>packages/prismarine/src/{Console.ts,command/ConsoleSender.ts,Server.ts,console/RemoteLogTransport.ts}</code>. <code>packages/server/src/host</code>, <code>packages/console/src/{help,app}</code>, and <code>RemoteConsole</code> were skipped as in progress. Judged against <code>AGENTS.md</code>, the codebase-design and unslop skills, and <code>plan.md</code>.</p><h2 id="checks-run" tabindex="-1">Checks run <a class="header-anchor" href="#checks-run" aria-label="Permalink to “Checks run”">​</a></h2><table tabindex="0"><thead><tr><th>Check</th><th>Result</th></tr></thead><tbody><tr><td><code>pnpm exec biome lint &lt;scope&gt;</code></td><td>67 files, no diagnostics. Warns that <code>biome.json</code> declares schema 2.6.2 while the CLI is 2.6.3 (pre-existing, outside this change).</td></tr><tr><td><code>pnpm exec prettier --check &lt;scope&gt;</code></td><td>All files formatted.</td></tr><tr><td><code>node scripts/check-unicode-escapes.mts</code></td><td>Pass, 2299 files.</td></tr><tr><td><code>node scripts/check-american-filenames.mts</code></td><td>Pass.</td></tr><tr><td><code>node scripts/check-jsdoc.mts</code></td><td>Pass, no new exports without JSDoc.</td></tr><tr><td><code>pnpm exec vitest run &lt;scope&gt;</code></td><td>26 files, 236 tests pass on Node 26.12.1.</td></tr><tr><td><code>pnpm --filter console --filter console-protocol run typecheck</code></td><td>Pass.</td></tr></tbody></table><p>Nothing in scope fails <code>pnpm run lint</code>. No <code>as</code> cast lacks a reason comment; the one cast (<code>minecraftColors.ts:120</code>) is commented. No British spellings found in scope.</p><h2 id="counts" tabindex="-1">Counts <a class="header-anchor" href="#counts" aria-label="Permalink to “Counts”">​</a></h2><p>Bug 3, design 7, nit 10, lint failure 0.</p><h2 id="findings-by-slice-owner" tabindex="-1">Findings by slice owner <a class="header-anchor" href="#findings-by-slice-owner" aria-label="Permalink to “Findings by slice owner”">​</a></h2><h3 id="logger-owner-of-packages-logger" tabindex="-1">Logger (owner of <code>packages/logger</code>) <a class="header-anchor" href="#logger-owner-of-packages-logger" aria-label="Permalink to “Logger (owner of packages/logger)”">​</a></h3><ol><li><strong>design</strong>, <code>packages/logger/src/logger.ts:13</code>, <code>packages/logger/src/transport.ts:99</code>. The level order is a private <code>LEVEL_WEIGHT</code> constant written twice inside the logger, and consumers copy it again (<code>prismarine/src/console/RemoteLogTransport.ts:5</code>, <code>console/src/log/types.ts:8</code>, and the first six entries of <code>console/src/theme/theme.ts:10</code>). Five copies of one ordering violate the &quot;derive values from their source of truth&quot; rule, and <code>types.ts:5</code> says so in its own JSDoc. Fix: export one <code>LOG_LEVELS = [&#39;error&#39;, ..., &#39;silly&#39;] as const</code> from <code>@jsprismarine/logger</code>, derive <code>LogLevel</code> from it, replace both <code>LEVEL_WEIGHT</code> tables with <code>LOG_LEVELS.indexOf</code>, and add an <code>isLogLevel</code> guard. Then <code>types.ts</code> imports <code>LOG_LEVELS</code>, <code>theme.ts</code> builds <code>LEVEL_ROLES = [...LOG_LEVELS, &#39;dev&#39;]</code>, and <code>messages.ts</code> can validate <code>level</code> fields (finding 6).</li></ol><h3 id="protocol-owner-of-packages-console-protocol" tabindex="-1">Protocol (owner of <code>packages/console-protocol</code>) <a class="header-anchor" href="#protocol-owner-of-packages-console-protocol" aria-label="Permalink to “Protocol (owner of packages/console-protocol)”">​</a></h3><ol start="2"><li><strong>nit</strong>, <code>packages/console-protocol/src/messages.ts:113,132</code>. <code>level: &#39;string&#39;</code> and <code>state: &#39;string&#39;</code> accept any string, so <code>{ level: &#39;bogus&#39; }</code> passes <code>isServerMessage</code> and then <code>compareLevels</code> in the console treats it as more severe than <code>error</code> (<code>indexOf</code> returns -1). Fix: once finding 1 lands, add an <code>enum</code> kind to the field table backed by <code>LOG_LEVELS</code> and the lifecycle state list, and add a rejecting test.</li><li><strong>nit</strong>, <code>packages/console-protocol/src/childProcessLink.ts:56,82</code>. When <code>proc.send</code> exists but <code>proc.connected</code> is already false, the link is born closed and no <code>onClose</code> listener ever runs, so a server whose host disconnected during startup never learns to shut down. Fix: if <code>!proc.connected</code>, emit <code>close</code> on the next microtask after construction, or throw like the no-channel case.</li></ol><h3 id="line-console-and-sender-owner-of-prismarine-src-console-ts-consolesender-ts-server-ts" tabindex="-1">Line console and sender (owner of <code>prismarine/src/Console.ts</code>, <code>ConsoleSender.ts</code>, <code>Server.ts</code>) <a class="header-anchor" href="#line-console-and-sender-owner-of-prismarine-src-console-ts-consolesender-ts-server-ts" aria-label="Permalink to “Line console and sender (owner of prismarine/src/Console.ts, ConsoleSender.ts, Server.ts)”">​</a></h3><ol start="4"><li><strong>nit</strong>, <code>packages/prismarine/src/Server.ts:223</code> and <code>packages/prismarine/src/Console.ts:66</code>. <code>logger.setConsole(this.console)</code> runs in <code>Server.enable</code>, then <code>Console.enable</code> calls <code>setConsole(this)</code> again. One is redundant. Fix: drop the call in <code>Console.enable</code> and let the server own the hookup (its comment already explains the ordering), or the reverse.</li><li><strong>nit</strong>, <code>packages/prismarine/src/Console.ts:59,94</code>. <code>disable()</code> closes the readline but <code>enable()</code> returns early on the <code>enabled</code> flag, so a disable followed by enable never reads again. Nothing calls that sequence today (<code>Server.disable</code> does not disable the console), so this is latent. Fix: guard the chat subscription with <code>enabled</code> and the readline with <code>this.cli === undefined</code> separately.</li></ol><h3 id="remote-log-transport-owner-of-prismarine-src-console-remotelogtransport-ts" tabindex="-1">Remote log transport (owner of <code>prismarine/src/console/RemoteLogTransport.ts</code>) <a class="header-anchor" href="#remote-log-transport-owner-of-prismarine-src-console-remotelogtransport-ts" aria-label="Permalink to “Remote log transport (owner of prismarine/src/console/RemoteLogTransport.ts)”">​</a></h3><ol start="6"><li><strong>design</strong>, <code>packages/prismarine/src/console/RemoteLogTransport.ts:5</code>. Third copy of <code>LEVEL_WEIGHT</code>; see finding 1. Fix: import the comparison from <code>@jsprismarine/logger</code>.</li><li><strong>nit</strong>, <code>packages/prismarine/src/console/RemoteLogTransport.ts:144-168</code>. The transport never subscribes to <code>link.onClose</code>. After the link closes, every <code>send</code> returns <code>false</code>, so a full queue drains one record per <code>retryMs</code> tick for up to 100 seconds (5000 x 20 ms) on unref&#39;d timers, doing nothing useful. Fix: in the constructor, <code>link.onClose(() =&gt; { this.closed = true; this.queue = []; this.stopRetry(); })</code>, and store the unsubscribe for <code>close()</code>.</li></ol><h3 id="theme-owner-of-console-src-theme" tabindex="-1">Theme (owner of <code>console/src/theme</code>) <a class="header-anchor" href="#theme-owner-of-console-src-theme" aria-label="Permalink to “Theme (owner of console/src/theme)”">​</a></h3><ol start="8"><li><strong>design</strong>, <code>packages/console/src/theme/theme.ts:10,45</code>. Components do not consume <code>Theme</code>. <code>status/segments.ts:20</code> defines <code>StatusColors</code> as <code>Record&lt;SegmentTone, string&gt; &amp; { text; background: string }</code> and <code>input/inputBar.ts:26-31</code> takes four <code>string</code> colors, while <code>Theme</code> values are <code>ColorInput</code> (<code>string | RGBA</code>) and <code>defaultTheme.text</code> and <code>.background</code> are <code>RGBA</code> instances. The app slice cannot pass <code>theme.text</code> to either component without a cast. Fix: define the plan&#39;s <code>ConsoleContext = { renderer, theme, ... }</code> once (for example <code>src/context.ts</code>), have <code>createStatusBar</code>, <code>createToastStack</code>, <code>createInputBar</code>, and <code>createLogView</code> take <code>Pick&lt;ConsoleContext, &#39;renderer&#39; | &#39;theme&#39;&gt;</code>, and delete <code>StatusColors</code> and the four color props. <code>SegmentTone</code> already matches <code>Theme</code> role names (<code>ok</code>, <code>warning</code>, <code>danger</code>, <code>muted</code>, <code>accent</code>), so <code>theme[segment.tone]</code> works as is. <code>logView.ts</code> already takes <code>theme</code> through props and is the model.</li><li><strong>nit</strong>, <code>packages/console/src/theme/theme.ts:10</code> and <code>styled.ts:30</code>. The <code>dev</code> level role is defined but nothing renders it: <code>StoredRecord</code> has no supervisor kind, and <code>plan.md</code> says supervisor state renders as a status segment and toasts, never as log lines. Fix: drop <code>dev</code> from <code>LEVEL_ROLES</code> and <code>LEVEL_ATTRIBUTES</code>, or leave a one-line note that the host slice adds the record kind.</li></ol><h3 id="log-store-and-view-owner-of-console-src-log" tabindex="-1">Log store and view (owner of <code>console/src/log</code>) <a class="header-anchor" href="#log-store-and-view-owner-of-console-src-log" aria-label="Permalink to “Log store and view (owner of console/src/log)”">​</a></h3><ol start="10"><li><strong>bug</strong>, <code>packages/console/src/log/logWindow.ts:88-98</code>. <code>onReset</code> and <code>onResize</code> while paused clamp <code>first</code> but never recompute <code>following</code>. When a filter change shrinks the list so the whole thing fits, the window sits at the bottom with <code>following === false</code>, so later appends scroll out of view and the badge reads &quot;N new lines, End to follow&quot; while the user already is at the end. Fix: after clamping in both methods, set <code>this.following = this.first === this.maxOffset</code> (the same rule <code>moveTo</code> applies), and add a <code>logWindow.test.ts</code> case.</li><li><strong>design</strong>, <code>packages/console/src/log/types.ts:8</code>. Second copy of the level order; see finding 1.</li><li><strong>design</strong>, <code>packages/console/src/log/logLine.ts:17,30-37,93-99</code>. <code>levelWidth: &#39;full&#39; | &#39;short&#39;</code> names a style, not a width, and <code>short</code> emits three-letter tokens where <code>ux-design.md</code> section 1 (which <code>plan.md</code> says to follow) specifies one letter below 100 columns. Fix: rename to <code>levelStyle</code> in <code>LogLineOptions</code> and <code>LogViewProps</code>, and either switch to one letter or record the three-letter decision in <code>ux-design.md</code> so the two agree.</li><li><strong>nit</strong>, <code>packages/console/src/log/logStore.ts:97</code> and <code>logLine.ts:73</code>. The text <code>${count} log lines were dropped</code> is built in both files. Fix: <code>logLine.ts</code> renders <code>record.message</code>, which <code>appendDropped</code> already fills.</li><li><strong>nit</strong>, <code>packages/console/src/log/logLine.ts:5</code>. Value import from the <code>../theme</code> barrel (<code>theme/index.ts</code> is an <code>export *</code> file). The brief lists &quot;no barrel value imports&quot; as a rule; I did not find it written in <code>AGENTS.md</code>, so treat as the reviewer&#39;s convention. Fix: import from <code>../theme/styled</code> and <code>../theme/theme</code>, or make <code>theme/index.ts</code> export names explicitly.</li><li><strong>nit</strong>, <code>packages/console/src/log/logLine.ts:101,153</code> versus <code>status/segments.ts:32</code>. The log line measures width in UTF-16 units (<code>.length</code>) while segments count code points (<code>[...text].length</code>). A message with an astral-plane character misaligns the ellipsis cut by one column. Fix: share one <code>columns()</code> helper (code points) between the two modules.</li><li><strong>nit</strong>, <code>packages/console/src/log/logLine.ts:183</code>. <code>plainChunk(&#39;&#39;, theme, &#39;selection&#39;).fg</code> builds a throwaway chunk to get an <code>RGBA</code>. Fix: <code>parseColor(theme.selection)</code>.</li><li><strong>nit</strong>, <code>packages/console/src/log/logStore.ts:76-81,242</code>. <code>matches</code> is invalidated on every push and recomputed by a full scan of the visible list on the next read. A status segment that shows the match count will scan up to 10 000 records per log line while a search is open. Fix: maintain the match list incrementally in <code>push</code> (append the new index when it matches, decrement all on a visible eviction) and only rebuild in <code>rebuild()</code>/<code>setSearch</code>.</li><li><strong>nit</strong>, test gap, <code>packages/console/src/log/logView.test.ts</code>. No test that <code>dispose()</code> unsubscribes from the store and cancels the pending frame (append after dispose must not paint or throw). Add one; same for <code>statusBar.test.ts</code> and the <code>RESIZE</code> listener.</li></ol><h3 id="input-bar-history-completion-owner-of-console-src-input" tabindex="-1">Input bar, history, completion (owner of <code>console/src/input</code>) <a class="header-anchor" href="#input-bar-history-completion-owner-of-console-src-input" aria-label="Permalink to “Input bar, history, completion (owner of console/src/input)”">​</a></h3><ol start="19"><li><strong>bug</strong>, <code>packages/console/src/input/inputBar.ts:167-181,203-205</code>. Completion race: Tab captures <code>line</code> and <code>cursor</code>, the user types (<code>edit</code> action, which does not touch <code>completionRequest</code>), then the result arrives with <code>request === completionRequest</code> and <code>applyCompletion</code> overwrites the line with the stale prefix and suffix, discarding what was typed. The existing test only covers a newer Tab superseding an older one. Fix: in <code>handleKey</code>, bump <code>completionRequest</code> for every action other than <code>cycle</code> and <code>complete</code> (or compare <code>input.value === line &amp;&amp; input.cursorOffset === cursor</code> before applying), and add a test that types between Tab and the resolved promise.</li><li><strong>bug</strong>, <code>packages/console/src/input/keys.ts:47-53</code> versus <code>keymap/catalog.ts:49-67</code>. Two key maps bind the same empty-line keys. <code>keys.ts</code> decodes <code>?</code>, <code>w</code>, <code>g</code>, <code>G</code>, <code>/</code> into <code>toggle</code> actions; the catalog binds <code>?</code>, <code>w</code>, <code>/</code> too (as <code>view.help</code>, <code>log.toggleWrap</code>, <code>log.search</code>). When the app wires both <code>resolveCommand</code> and <code>onToggle</code>, one <code>w</code> press toggles wrap twice (a no-op) and <code>?</code> opens and closes help. Conversely <code>n</code>, <code>N</code>, <code>Home</code>, <code>End</code> exist only in the catalog, so the input bar types <code>n</code> into the line unless the app intercepts first, and <code>g</code>/<code>G</code> exist only in <code>keys.ts</code>, so the help overlay (generated from the catalog) never lists them even though <code>ux-design.md</code> section 6 does. Fix: make the catalog the single source. Add <code>empty(&#39;g&#39;)</code> and <code>empty(&#39;g&#39;, true)</code> to <code>log.top</code>/<code>log.bottom</code>, delete <code>TOGGLE_KEYS</code> and the <code>toggle</code> action from <code>keys.ts</code>, and have the app call <code>resolveCommand(key, { inputEmpty })</code> before the input bar&#39;s handler (with <code>preventDefault</code> on a hit). If the input bar must stay self-contained, derive <code>TOGGLE_KEYS</code> from <code>COMMAND_CATALOG</code> entries whose binding is <code>emptyLineOnly</code> with a single-character name.</li><li><strong>design</strong>, <code>packages/console/src/input/inputBar.ts:26-31</code>. Four <code>string</code> color props; see finding 8.</li><li><strong>nit</strong>, <code>packages/console/src/input/inputBar.ts:149</code>. The completion strip is laid out against <code>renderer.terminalWidth</code> once and not re-laid out on <code>RESIZE</code>. Fix: subscribe to <code>CliRenderEvents.RESIZE</code> like <code>statusBar.ts:99</code> does and remove it in <code>dispose</code>, or let the <code>TextRenderable</code> truncate.</li></ol><h3 id="status-bar-segments-toasts-owner-of-console-src-status" tabindex="-1">Status bar, segments, toasts (owner of <code>console/src/status</code>) <a class="header-anchor" href="#status-bar-segments-toasts-owner-of-console-src-status" aria-label="Permalink to “Status bar, segments, toasts (owner of console/src/status)”">​</a></h3><ol start="23"><li><strong>design</strong>, <code>packages/console/src/status/segments.ts:20-23</code>, <code>statusBar.ts:10-12</code>, <code>toasts.ts</code>. <code>StatusColors</code> and a private <code>StatusContext { renderer }</code>; see finding 8.</li><li><strong>nit</strong>, <code>packages/console/src/status/toastQueue.ts:67-70</code>. When every existing toast is sticky and the queue is full, pushing a non-sticky toast evicts the toast just pushed and still returns its id, so the caller shows nothing. Fix: exclude the new toast from eviction (search <code>entries.slice(0, -1)</code>), falling back to the oldest sticky one.</li></ol><h3 id="scaffold-owner-of-packages-console-root" tabindex="-1">Scaffold (owner of <code>packages/console</code> root) <a class="header-anchor" href="#scaffold-owner-of-packages-console-root" aria-label="Permalink to “Scaffold (owner of packages/console root)”">​</a></h3><ol start="25"><li><strong>nit</strong>, <code>packages/console/src/opentui.test.ts</code>. A smoke test of the dependency, not of this package. It earned its keep during the spike; now that every component has a renderer test it only adds a second <code>createTestRenderer</code> boot. Fix: delete it, or keep it only if the Node 26 FFI gate is what it is meant to prove and say so in the describe name.</li></ol><h2 id="not-findings-checked" tabindex="-1">Not findings, checked <a class="header-anchor" href="#not-findings-checked" aria-label="Permalink to “Not findings, checked”">​</a></h2><ul><li>Ring buffer arithmetic in <code>logStore.ts:190-216</code> (<code>start</code>, <code>count</code>, wrap, <code>hidden</code> bookkeeping on eviction) is correct and covered by <code>logStore.test.ts:188-222</code>.</li><li><code>LogWindow.onAppended</code> with <code>evicted</code> while paused is correct (<code>logWindow.test.ts:46</code>).</li><li><code>statusBar.dispose</code> removes the <code>RESIZE</code> listener; <code>toasts.dispose</code> clears the timer; <code>logView.dispose</code> unsubscribes and cancels the frame. <code>Renderable.remove(child)</code> and <code>requestAnimationFrame</code> exist on OpenTUI 0.6.8 with the signatures used.</li><li><code>childProcessLink.flush</code> resolves on disconnect (<code>pending = 0; settle()</code>), so the shutdown path in <code>Server.shutdown</code> cannot hang on a dead channel.</li><li><code>RemoteLogTransport.resume</code> cannot spin: each iteration consumes one queued record and a <code>false</code> send exits the loop before the next async resume.</li><li><code>Server.ts</code> at <code>HEAD</code> imports <code>./console/RemoteConsole</code>; the file looked untracked in the initial status snapshot but commit <code>96124d669b</code> added it while this review ran. Not a finding.</li></ul></div>',1)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};